-- ###########################################################################
-- SECTION 1 of 10 : 0054_sales_never_overdraw_and_imported_edit_keeps_its_stock.sql
-- ###########################################################################

    -- ---------------------------------------------------------------------------
    -- 0054. A sale never overdraws its bucket, and correcting an imported sale no
    -- longer hands its carats back.
    --
    --
    -- 1 . POSTING STILL LET A SALE TAKE A BUCKET NEGATIVE
    --
    -- 0053 stopped the sales-entry HOLD overdrawing a bucket, but left post_invoice
    -- on negative_stock_policy(): under 'allow' it posted whatever was typed, and
    -- under 'warn' a caller passing p_override did the same. The desk's rule is
    -- that stock never goes negative from a sale, so it now refuses a shortfall
    -- whatever the policy says.
    --
    -- Same check, same place, same text: the shortfall is still raised as
    -- "Posting would take stock negative: [...]", which is what Repo.RaisedShortfalls
    -- already lifts into the "Not enough stock" box, naming each bucket with what it
    -- needs and what it has. PER BUCKET as it always was -- (grade_id, size_id) --
    -- so stock in another grade or sieve can never cover a shortfall.
    --
    --
    -- 2 . "UPDATE SALE" ON AN IMPORTED (MIG-) INVOICE GAVE ITS STOCK BACK
    --
    -- 0042 was written when an imported invoice carried no movements: it moved the
    -- DIFFERENCE between old and new lines as an import_edit ADJUST. 0049 changed
    -- the premise -- every imported line now writes SALE/REJECTION tagged
    -- 'sales_line' -- and edit_posted_invoice did not follow. Its step 1 deletes
    -- those movements for EVERY invoice, imported ones included, and then for an
    -- imported invoice writes only the difference. So one update:
    --
    --   * returned every carat the invoice had taken, in every bucket on it, and
    --   * then applied the difference on top -- a removed line's carats came back
    --     twice, and an unchanged line's came back once.
    --
    -- The balance read high by the whole invoice, and v_reconciliation (0052,
    -- which counts imported SALE movements) reported the invoice as unsold.
    --
    -- Now an imported invoice is rewritten exactly as the import writes it: its
    -- movements deleted, then written again from the corrected lines, CAPPED at
    -- what each bucket holds -- 0051's rule, so an imported sale still never drives
    -- stock negative and a capped line stays capped. Any import_edit adjustment an
    -- earlier update left on the invoice is removed in the same transaction, or it
    -- would count a second time on top of the rewritten movements.
    --
    -- An ordinary invoice is unchanged except for the guard: a correction the
    -- bucket cannot cover is refused whatever the policy, naming both figures.
    --
    -- Existing data: an imported invoice already updated under 0042 holds an
    -- import_edit ADJUST and no SALE movements. The next update of it, or the next
    -- sales re-import, rewrites it correctly. DIAGNOSE_STOCK_DRIFT.sql lists them.
    --
    -- SUPERSEDES 0019's post_invoice and 0042's edit_posted_invoice. Grants are kept
    -- by create or replace. Writes no movement when applied. Safe to run repeatedly.
    -- ---------------------------------------------------------------------------

    begin;

    create or replace function public.post_invoice(
        p_invoice_id bigint,
        p_override   boolean default false
    )
    returns jsonb
    language plpgsql
    as $$
    declare
        v_status text;
        v_date   date;
        v_short  jsonb;
        v_no     varchar(20);
    begin
        select status, invoice_date into v_status, v_date
        from public.sales_invoice
        where invoice_id = p_invoice_id;

        if not found then
            raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
        end if;

        if v_status = 'POSTED' then
            return jsonb_build_object('ok', true, 'already_posted', true);
        end if;

        if v_status = 'CANCELLED' then
            raise exception 'Invoice % is cancelled and cannot be posted', p_invoice_id;
        end if;

        if not exists (select 1 from public.sales_line where invoice_id = p_invoice_id) then
            raise exception 'Invoice % has no lines', p_invoice_id;
        end if;

        with need as (
            select grade_id, size_id, sum(gross_weight_ct) as out_ct
            from public.sales_line
            where invoice_id = p_invoice_id
            group by grade_id, size_id
        )
        select jsonb_agg(jsonb_build_object(
                'grade_code', sp.grade_code,
                'size_code',  sp.size_code,
                'balance_ct', greatest(sp.balance_ct, 0),
                'needed_ct',  n.out_ct))
        into v_short
        from need n
        join public.v_stock_position sp
            on sp.grade_id = n.grade_id and sp.size_id = n.size_id
        where sp.balance_ct < n.out_ct;

        -- 0054. Whatever the policy, and whatever p_override says. See the header.
        if v_short is not null then
            raise exception 'Posting would take stock negative: %', v_short::text
                using errcode = 'check_violation';
        end if;

        update public.sales_line l
        set cost_per_ct = nullif(sp.avg_cost, 0),
            cost_basis  = case when nullif(sp.avg_cost, 0) is null
                                then null else 'moving_average' end
        from public.v_stock_position sp
        where l.invoice_id = p_invoice_id
        and sp.grade_id  = l.grade_id
        and sp.size_id   = l.size_id;

        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
            price_per_ct, ref_type, ref_id, created_by)
        select v_date, l.grade_id, l.size_id, 'SALE', l.selection_ct,
            l.price_per_ct, 'sales_line', l.line_id, auth.uid()
        from public.sales_line l
        where l.invoice_id = p_invoice_id and l.selection_ct > 0;

        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
            price_per_ct, ref_type, ref_id, created_by)
        select v_date, l.grade_id, l.size_id, 'REJECTION', l.rejection_ct,
            l.price_per_ct, 'sales_line', l.line_id, auth.uid()
        from public.sales_line l
        where l.invoice_id = p_invoice_id and l.rejection_ct > 0;

        update public.sales_invoice
        set status     = 'POSTED',
            invoice_no = coalesce(invoice_no, public.next_invoice_no(v_date)),
            updated_by = auth.uid()
        where invoice_id = p_invoice_id;

        select invoice_no into v_no from public.sales_invoice where invoice_id = p_invoice_id;
        return jsonb_build_object('ok', true, 'invoice_no', v_no);
    end;
    $$;

    comment on function public.post_invoice(bigint, boolean) is
        '0054. Posts a draft: per grade x size bucket, refuses when the bucket cannot cover the invoice (whatever negative_stock_policy says, and p_override is ignored), then stamps cost, writes SALE/REJECTION and assigns the number. Supersedes 0019.';


    create or replace function public.edit_posted_invoice(
        p_invoice_id   bigint,
        p_invoice_date date,
        p_buyer_id     bigint,
        p_broker_id    bigint,
        p_broker_pct   numeric,
        p_terms_days   integer,
        p_doc_type     text,
        p_currency_id  bigint,
        p_lines        jsonb,
        p_reason       text
    )
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
        v_status   text;
        v_no       text;
        v_short    text;
        v_reason   text := btrim(coalesce(p_reason, ''));
        v_note     text;
        v_imported boolean;
    begin
        select status, invoice_no
        into v_status, v_no
        from public.sales_invoice
        where invoice_id = p_invoice_id
        for update;

        if not found then
            raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
        end if;

        if v_status = 'DRAFT' then
            raise exception 'Invoice % is a draft; save it the ordinary way', p_invoice_id;
        end if;

        if v_status = 'CANCELLED' then
            raise exception 'Invoice % is cancelled. Its stock has already been returned, so there is nothing to correct.', p_invoice_id;
        end if;

        if v_status <> 'POSTED' then
            raise exception 'Invoice % is %, which cannot be edited', p_invoice_id, v_status;
        end if;

        v_imported := coalesce(v_no, '') like 'MIG-%';

        if v_reason = '' then
            raise exception 'Correcting a posted invoice requires a reason';
        end if;

        if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
            raise exception 'An invoice must keep at least one line. To remove it entirely, cancel it.';
        end if;

        v_note := 'Edit of invoice ' || coalesce(v_no, p_invoice_id::text) || ': ' || v_reason;

        -- ── 1 · give the stock back ────────────────────────────────────────────
        -- Every invoice, imported or not: since 0049 both carry SALE/REJECTION tagged sales_line.
        delete from public.stock_movement m
        using public.sales_line l
        where m.ref_type = 'sales_line'
        and m.ref_id = l.line_id
        and l.invoice_id = p_invoice_id
        and m.movement_type in ('SALE', 'REJECTION');

        -- 0054. And whatever an update under 0042 left behind, or it counts again on top of step 6.
        perform public.clear_import_edits(array[p_invoice_id]);

        -- ── 2 · the old lines go with them ─────────────────────────────────────
        delete from public.sales_line where invoice_id = p_invoice_id;

        -- ── 3 · the corrected lines ────────────────────────────────────────────
        insert into public.sales_line
            (invoice_id, grade_id, size_id, gross_weight_ct, selection_ct,
            price_per_ct, ex_rate, less1_pct, less2_pct, remark)
        select p_invoice_id,
            (r->>'grade_id')::bigint,
            (r->>'size_id')::bigint,
            (r->>'gross_weight_ct')::numeric,
            (r->>'selection_ct')::numeric,
            (r->>'price_per_ct')::numeric,
            coalesce(nullif((r->>'ex_rate')::numeric, 0), 1),
            coalesce((r->>'less1_pct')::numeric, 0),
            coalesce((r->>'less2_pct')::numeric, 0),
            nullif(btrim(coalesce(r->>'remark', '')), '')
        from jsonb_array_elements(p_lines) as r;

        -- ── 4 · an ordinary invoice: the bucket covers it, or nothing changes ──
        -- Refused whatever the policy (0054), per bucket, both figures named. The stock is back at
        -- its pre-invoice level by now, so this is the whole of what the invoice now says left it.
        -- An imported invoice is not refused here: it is capped in step 6, as the import caps it.
        if not v_imported then
            select string_agg(format('Insufficient stock for %s x %s: required %s ct, available %s ct.',
                                    sp.grade_code, sp.size_code,
                                    trim_scale(round(n.out_ct, 4)),
                                    trim_scale(round(greatest(sp.balance_ct, 0), 4))), ' ')
            into v_short
            from (select grade_id, size_id, sum(gross_weight_ct) as out_ct
                    from public.sales_line
                    where invoice_id = p_invoice_id
                    group by grade_id, size_id) n
            join public.v_stock_position sp
                on sp.grade_id = n.grade_id and sp.size_id = n.size_id
            where sp.balance_ct < n.out_ct;

            if v_short is not null then
                raise exception '%', v_short using errcode = 'check_violation';
            end if;
        end if;

        -- ── 5 · the cost stamp, as posting does it (0019); imported lines stay uncosted ──
        update public.sales_line l
        set cost_per_ct = nullif(sp.avg_cost, 0),
            cost_basis  = case when nullif(sp.avg_cost, 0) is null
                                then null else 'moving_average' end
        from public.v_stock_position sp
        where l.invoice_id = p_invoice_id
        and not v_imported
        and sp.grade_id  = l.grade_id
        and sp.size_id   = l.size_id;

        -- ── 6 · and the stock leaves again ─────────────────────────────────────
        -- An ordinary invoice in full (step 4 proved it fits). An imported one up to what each bucket
        -- holds, lines in order, sale before rejection -- 0051's rule, scoped to this invoice.
        with wanted as (
            select l.line_id, l.grade_id, l.size_id, l.price_per_ct,
                coalesce(l.selection_ct, 0) as selection_ct,
                coalesce(l.rejection_ct, 0) as rejection_ct,
                coalesce(l.selection_ct, 0) + coalesce(l.rejection_ct, 0) as gross_ct
            from public.sales_line l
            where l.invoice_id = p_invoice_id
        ),
        capped as (
            select w.*,
                case when not v_imported then w.gross_ct
                        else greatest(0, least(w.gross_ct,
                                greatest(coalesce(p.balance_ct, 0), 0)
                                - coalesce(sum(w.gross_ct) over (partition by w.grade_id, w.size_id
                                                                order by w.line_id
                                                                rows between unbounded preceding and 1 preceding), 0)))
                end as allow_ct
            from wanted w
            left join public.v_stock_position p
                    on p.grade_id = w.grade_id and p.size_id = w.size_id
        ),
        split as (
            select c.*,
                least(c.selection_ct, c.allow_ct) as sale_out,
                least(c.rejection_ct, c.allow_ct - least(c.selection_ct, c.allow_ct)) as rej_out
            from capped c
        )
        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
            price_per_ct, ref_type, ref_id, created_by, reason)
        select p_invoice_date, s.grade_id, s.size_id, 'SALE', s.sale_out,
            s.price_per_ct, 'sales_line', s.line_id, auth.uid(), v_note
        from split s where s.sale_out > 0
        union all
        select p_invoice_date, s.grade_id, s.size_id, 'REJECTION', s.rej_out,
            s.price_per_ct, 'sales_line', s.line_id, auth.uid(), v_note
        from split s where s.rej_out > 0;

        -- ── 7 · the header, keeping the number and the status ──────────────────
        update public.sales_invoice
        set invoice_date = p_invoice_date,
            buyer_id     = p_buyer_id,
            broker_id    = p_broker_id,
            broker_pct   = p_broker_pct,
            terms_days   = p_terms_days,
            doc_type     = p_doc_type,
            currency_id  = p_currency_id,
            updated_by   = auth.uid()
        where invoice_id = p_invoice_id;

        return jsonb_build_object('ok', true, 'invoice_no', v_no, 'reason', v_reason);
    end;
    $$;

    comment on function public.edit_posted_invoice is
        '0054. Corrects a POSTED invoice in one transaction: deletes its SALE/REJECTION movements (and any 0042 import_edit adjustment), replaces its lines and writes the movements again. An ordinary invoice is refused, per bucket and whatever the policy, when the bucket cannot cover it. An imported MIG- invoice is capped at what each bucket holds, as replace_imported_sales (0051) caps it. Supersedes 0042, which returned an imported invoice''s carats on every update once 0049 gave those invoices movements.';

    commit;


    -- ---------------------------------------------------------------------------
    -- Verification. Every row must read 'ok'.
    -- ---------------------------------------------------------------------------
    select 'posting refuses a shortfall whatever the policy' as check,
        case when pg_get_functiondef('public.post_invoice'::regproc) not like '%negative_stock_policy%'
                and pg_get_functiondef('public.post_invoice'::regproc) like '%Posting would take stock negative%'
                then 'ok' else 'NOT APPLIED' end as status
    union all
    select 'an update no longer moves an imported invoice by difference',
        case when pg_get_functiondef('public.edit_posted_invoice'::regproc) not like '%imported_edit_delta%'
                and pg_get_functiondef('public.edit_posted_invoice'::regproc) like '%clear_import_edits%'
                then 'ok' else 'NOT APPLIED' end
    union all
    select 'the import cap is still 0051''s',
        case when pg_get_functiondef('public.replace_imported_sales'::regproc) like '%short_buckets%'
                then 'ok' else '0051 IS MISSING' end;


-- ###########################################################################
-- SECTION 2 of 10 : 0055_rejection_never_reduces_stock.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0055. Only SOLD carats leave stock. A rejection is a record, never a deduction.
--
-- APPLY AFTER 0054. Back the database up first (tests/probes/tool-backup-tables.cs.txt).
-- ROLLBACK: supabase/ROLLBACK_0055.sql.
--
--
-- THE RULE
--
-- A sale line is gross = selection + rejection. Until now every path took the
-- WHOLE gross out of the bucket: post_invoice and the sales import wrote a SALE
-- for the selection and a REJECTION for the rest, and v_stock_position
-- subtracted both. From here on only the SALE leaves stock:
--
--   v_stock_position      a REJECTION row counts 0. It is still in the ledger,
--                         still listed on the Rejections screen, still on the
--                         invoice -- it just no longer moves the balance.
--   post_invoice          a bucket must cover the SELECTION, not the gross.
--   edit_posted_invoice   the same, and an imported invoice is capped on its
--                         selection (0051's rule, now on what actually leaves).
--   replace_imported_sales  caps and reports on the selection; the rejection is
--                         written in full as a record.
--   cancel_invoice        gives back the SALE only -- the rejection was never
--                         taken, so crediting it would be a credit for nothing.
--   record_rejection      no longer checks or moves stock.
--
-- This matches the specification: INV-005 / docs/03 §345 make a REJECTION
-- movement optional behind auto_reject_on_post, default FALSE, and DiamondApi
-- deducts the selection only. The Supabase functions always deducted both.
--
--
-- HISTORY IS NOT ADDED BACK
--
-- Every REJECTION already in the ledger took carats out under the old rule.
-- Simply ignoring them would put all of it back at once (439.90 ct on Priya)
-- with nobody having decided that it should. So, in this same transaction, each
-- of those deductions is restated as an explicit ADJUST:
--
--   ref_type 'rejection_hold'  one row per invoice x bucket, ref_id = invoice_id
--   ref_type 'rej_hold_mvmt'   one row per REJECTION not tied to an invoice line
--                              (recorded by hand), ref_id = that movement_id
--
-- Every bucket's balance is therefore IDENTICAL before and after this
-- migration; the last step checks that and rolls everything back if a single
-- bucket differs. The holds are what an approved correction later removes,
-- bucket by bucket or invoice by invoice -- see
-- supabase/REJECTION_CORRECTION_PLAN.md. Until then the screen shows exactly
-- what it showed before.
--
-- How the holds behave afterwards, so nothing is credited twice:
--   * cancelling an invoice that has a hold releases that hold too, which is
--     exactly what cancelling it did before 0055 (the whole gross came back);
--   * updating an invoice leaves its hold alone (the hold is keyed by invoice,
--     not by line, so it survives the lines being rewritten);
--   * a sales re-import does not delete holds (it only deletes its own
--     'sales_line' movements), so re-importing cannot add history back either.
--
-- Nothing else changes: conversions, adjustments, intake, stock imports,
-- reservations, release-on-post, reconciliation, numbering, costing.
-- ---------------------------------------------------------------------------

begin;

-- ── 0 · the position as it stands, to prove it does not move ────────────────
create temporary table m0055_before on commit drop as
select grade_id, size_id, ledger_ct from public.v_stock_position;


-- ── 1 · restate every existing rejection deduction as an explicit hold ───────
-- Only on the FIRST run: a second run must not hold rejections written after 0055.
do $$
begin
    if exists (select 1 from public.stock_movement
                where ref_type in ('rejection_hold', 'rej_hold_mvmt')) then
        raise notice '0055: holds already exist, not created again';
        return;
    end if;

    -- trg_reject_retired_size refuses any new row on a retired sieve, and a hold IS a new row.
    -- Said plainly up front rather than failing half way (it would roll back either way).
    if exists (select 1 from public.stock_movement m
                 join public.size_bucket s on s.size_id = m.size_id
                where m.movement_type = 'REJECTION' and not s.active) then
        raise exception '0055: some rejections are on a retired sieve, so their hold cannot be written. '
                        'Restore those sieves on Master data, apply 0055, then retire them again. Nothing was applied.';
    end if;

    -- Rejections off an invoice line: one hold per invoice x bucket.
    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct, ref_type, ref_id, reason)
    select min(m.movement_date), m.grade_id, m.size_id, 'ADJUST', -sum(m.weight_ct),
           'rejection_hold', l.invoice_id,
           '0055: rejection deducted under the old rule, kept out of stock pending review (invoice '
           || coalesce(max(i.invoice_no), l.invoice_id::text) || ')'
      from public.stock_movement m
      join public.sales_line l    on l.line_id = m.ref_id
      join public.sales_invoice i on i.invoice_id = l.invoice_id
     where m.movement_type = 'REJECTION' and m.ref_type = 'sales_line'
     group by l.invoice_id, m.grade_id, m.size_id
    having sum(m.weight_ct) <> 0;

    -- Every other rejection (recorded by hand, or a line that no longer exists): one hold each.
    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct, ref_type, ref_id, reason)
    select m.movement_date, m.grade_id, m.size_id, 'ADJUST', -m.weight_ct,
           'rej_hold_mvmt', m.movement_id,
           '0055: rejection deducted under the old rule, kept out of stock pending review (movement '
           || m.movement_id || ')'
      from public.stock_movement m
     where m.movement_type = 'REJECTION'
       and m.weight_ct <> 0
       and not (m.ref_type = 'sales_line'
                and exists (select 1 from public.sales_line l where l.line_id = m.ref_id));
end;
$$;


-- ── 2 · the position: a REJECTION row no longer moves the balance ───────────
-- 0044's view, column for column; the only change is the REJECTION arm of signed_ct.
create or replace view public.v_stock_position as
with movement as (
    select
        m.grade_id,
        m.size_id,
        case when m.movement_type in ('INTAKE', 'CONVERT_IN') then m.weight_ct
             when m.movement_type = 'ADJUST'                  then m.weight_ct
             when m.movement_type = 'REJECTION'               then 0      -- 0055: a record, not a deduction
             else -m.weight_ct end                            as signed_ct,
        case when m.movement_type in ('INTAKE', 'CONVERT_IN') then m.weight_ct
             when m.movement_type = 'ADJUST' and m.weight_ct > 0 then m.weight_ct
             else 0 end                                       as inward_ct,
        case when m.movement_type in ('INTAKE', 'CONVERT_IN')
             then m.weight_ct * coalesce(m.price_per_ct, 0)
             when m.movement_type = 'ADJUST' and m.weight_ct > 0
             then m.weight_ct * coalesce(m.price_per_ct, 0)
             else 0 end                                       as inward_value,
        case when m.movement_type in ('INTAKE', 'CONVERT_IN')
             then m.movement_date end                         as inward_date
    from public.stock_movement m
),
held as (
    select r.grade_id, r.size_id, sum(r.weight_ct) as reserved_ct
      from public.stock_reservation r
     group by r.grade_id, r.size_id
)
select
    g.grade_id,
    g.code                          as grade_code,
    g.display_name                  as grade_name,
    s.size_id,
    s.code                          as size_code,
    round(coalesce(sum(mv.signed_ct), 0) - coalesce(min(h.reserved_ct), 0), 4) as balance_ct,
    case when coalesce(sum(mv.inward_ct), 0) > 0
         then sum(mv.inward_value) / sum(mv.inward_ct)
         else 0 end                           as avg_cost,
    round(
        greatest(coalesce(sum(mv.signed_ct), 0) - coalesce(min(h.reserved_ct), 0), 0)
        * case when coalesce(sum(mv.inward_ct), 0) > 0
               then sum(mv.inward_value) / sum(mv.inward_ct)
               else 0 end
    , 2)                                      as stock_value,
    min(mv.inward_date)                       as oldest_intake,
    current_date - min(mv.inward_date)        as age_days,
    round(coalesce(sum(mv.signed_ct), 0), 4)                                   as ledger_ct,
    round(coalesce(min(h.reserved_ct), 0), 4)                                  as reserved_ct
from public.grade g
cross join public.size_bucket s
left join movement mv on mv.grade_id = g.grade_id and mv.size_id = s.size_id
left join held h      on h.grade_id  = g.grade_id and h.size_id  = s.size_id
group by g.grade_id, g.code, g.display_name, s.size_id, s.code;

comment on view public.v_stock_position is
    'CALC-6/7. Balance, average cost and value per grade x size. 0055: only SOLD carats leave stock -- a REJECTION movement is a record and counts 0; rejections deducted before 0055 are held as explicit ADJUST rows (ref_type rejection_hold / rej_hold_mvmt). balance_ct is AVAILABLE (net of sales-entry reservations, 0043); ledger_ct is HELD (0044); reserved_ct is the difference.';


-- ── 3 · posting: the bucket must cover what is SOLD ─────────────────────────
-- 0054's body; the need is the selection, not the gross.
create or replace function public.post_invoice(
    p_invoice_id bigint,
    p_override   boolean default false
)
returns jsonb
language plpgsql
as $$
declare
    v_status text;
    v_date   date;
    v_short  jsonb;
    v_no     varchar(20);
begin
    select status, invoice_date into v_status, v_date
      from public.sales_invoice
     where invoice_id = p_invoice_id;

    if not found then
        raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
    end if;

    if v_status = 'POSTED' then
        return jsonb_build_object('ok', true, 'already_posted', true);
    end if;

    if v_status = 'CANCELLED' then
        raise exception 'Invoice % is cancelled and cannot be posted', p_invoice_id;
    end if;

    if not exists (select 1 from public.sales_line where invoice_id = p_invoice_id) then
        raise exception 'Invoice % has no lines', p_invoice_id;
    end if;

    -- 0055. What LEAVES the bucket is the selection; the rejection stays in it.
    with need as (
        select grade_id, size_id, sum(selection_ct) as out_ct
          from public.sales_line
         where invoice_id = p_invoice_id
         group by grade_id, size_id
        having sum(selection_ct) > 0
    )
    select jsonb_agg(jsonb_build_object(
               'grade_code', sp.grade_code,
               'size_code',  sp.size_code,
               'balance_ct', greatest(sp.balance_ct, 0),
               'needed_ct',  n.out_ct))
      into v_short
      from need n
      join public.v_stock_position sp
        on sp.grade_id = n.grade_id and sp.size_id = n.size_id
     where sp.balance_ct < n.out_ct;

    -- 0054. Whatever the policy, and whatever p_override says.
    if v_short is not null then
        raise exception 'Posting would take stock negative: %', v_short::text
            using errcode = 'check_violation';
    end if;

    update public.sales_line l
       set cost_per_ct = nullif(sp.avg_cost, 0),
           cost_basis  = case when nullif(sp.avg_cost, 0) is null
                              then null else 'moving_average' end
      from public.v_stock_position sp
     where l.invoice_id = p_invoice_id
       and sp.grade_id  = l.grade_id
       and sp.size_id   = l.size_id;

    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct,
         price_per_ct, ref_type, ref_id, created_by)
    select v_date, l.grade_id, l.size_id, 'SALE', l.selection_ct,
           l.price_per_ct, 'sales_line', l.line_id, auth.uid()
      from public.sales_line l
     where l.invoice_id = p_invoice_id and l.selection_ct > 0;

    -- The rejection is still written: it is the record the Rejections screen and the history read.
    -- 0055: it no longer changes the balance (see v_stock_position).
    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct,
         price_per_ct, ref_type, ref_id, created_by)
    select v_date, l.grade_id, l.size_id, 'REJECTION', l.rejection_ct,
           l.price_per_ct, 'sales_line', l.line_id, auth.uid()
      from public.sales_line l
     where l.invoice_id = p_invoice_id and l.rejection_ct > 0;

    update public.sales_invoice
       set status     = 'POSTED',
           invoice_no = coalesce(invoice_no, public.next_invoice_no(v_date)),
           updated_by = auth.uid()
     where invoice_id = p_invoice_id;

    select invoice_no into v_no from public.sales_invoice where invoice_id = p_invoice_id;
    return jsonb_build_object('ok', true, 'invoice_no', v_no);
end;
$$;

comment on function public.post_invoice(bigint, boolean) is
    '0055. Posts a draft: per grade x size bucket, refuses when the bucket cannot cover the SELECTION (whatever the policy; p_override ignored), stamps cost, writes SALE (moves stock) and REJECTION (a record, moves nothing) and assigns the number. Supersedes 0054.';


-- ── 4 · correcting a posted invoice ─────────────────────────────────────────
-- 0054's body; the guard and the import cap are on the selection, and the rejection is written
-- in full as a record. Holds (ref_type rejection_hold) are keyed by invoice and left alone.
create or replace function public.edit_posted_invoice(
    p_invoice_id   bigint,
    p_invoice_date date,
    p_buyer_id     bigint,
    p_broker_id    bigint,
    p_broker_pct   numeric,
    p_terms_days   integer,
    p_doc_type     text,
    p_currency_id  bigint,
    p_lines        jsonb,
    p_reason       text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_status   text;
    v_no       text;
    v_short    text;
    v_reason   text := btrim(coalesce(p_reason, ''));
    v_note     text;
    v_imported boolean;
begin
    select status, invoice_no
      into v_status, v_no
      from public.sales_invoice
     where invoice_id = p_invoice_id
       for update;

    if not found then
        raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
    end if;

    if v_status = 'DRAFT' then
        raise exception 'Invoice % is a draft; save it the ordinary way', p_invoice_id;
    end if;

    if v_status = 'CANCELLED' then
        raise exception 'Invoice % is cancelled. Its stock has already been returned, so there is nothing to correct.', p_invoice_id;
    end if;

    if v_status <> 'POSTED' then
        raise exception 'Invoice % is %, which cannot be edited', p_invoice_id, v_status;
    end if;

    v_imported := coalesce(v_no, '') like 'MIG-%';

    if v_reason = '' then
        raise exception 'Correcting a posted invoice requires a reason';
    end if;

    if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
        raise exception 'An invoice must keep at least one line. To remove it entirely, cancel it.';
    end if;

    v_note := 'Edit of invoice ' || coalesce(v_no, p_invoice_id::text) || ': ' || v_reason;

    -- ── 1 · give the stock back ────────────────────────────────────────────
    delete from public.stock_movement m
     using public.sales_line l
     where m.ref_type = 'sales_line'
       and m.ref_id = l.line_id
       and l.invoice_id = p_invoice_id
       and m.movement_type in ('SALE', 'REJECTION');

    perform public.clear_import_edits(array[p_invoice_id]);

    -- ── 2 · the old lines go with them ─────────────────────────────────────
    delete from public.sales_line where invoice_id = p_invoice_id;

    -- ── 3 · the corrected lines ────────────────────────────────────────────
    insert into public.sales_line
        (invoice_id, grade_id, size_id, gross_weight_ct, selection_ct,
         price_per_ct, ex_rate, less1_pct, less2_pct, remark)
    select p_invoice_id,
           (r->>'grade_id')::bigint,
           (r->>'size_id')::bigint,
           (r->>'gross_weight_ct')::numeric,
           (r->>'selection_ct')::numeric,
           (r->>'price_per_ct')::numeric,
           coalesce(nullif((r->>'ex_rate')::numeric, 0), 1),
           coalesce((r->>'less1_pct')::numeric, 0),
           coalesce((r->>'less2_pct')::numeric, 0),
           nullif(btrim(coalesce(r->>'remark', '')), '')
      from jsonb_array_elements(p_lines) as r;

    -- ── 4 · an ordinary invoice: the bucket covers what is SOLD, or nothing changes ──
    if not v_imported then
        select string_agg(format('Insufficient stock for %s x %s: required %s ct, available %s ct.',
                                 sp.grade_code, sp.size_code,
                                 trim_scale(round(n.out_ct, 4)),
                                 trim_scale(round(greatest(sp.balance_ct, 0), 4))), ' ')
          into v_short
          from (select grade_id, size_id, sum(selection_ct) as out_ct
                  from public.sales_line
                 where invoice_id = p_invoice_id
                 group by grade_id, size_id
                having sum(selection_ct) > 0) n
          join public.v_stock_position sp
            on sp.grade_id = n.grade_id and sp.size_id = n.size_id
         where sp.balance_ct < n.out_ct;

        if v_short is not null then
            raise exception '%', v_short using errcode = 'check_violation';
        end if;
    end if;

    -- ── 5 · the cost stamp, as posting does it (0019); imported lines stay uncosted ──
    update public.sales_line l
       set cost_per_ct = nullif(sp.avg_cost, 0),
           cost_basis  = case when nullif(sp.avg_cost, 0) is null
                              then null else 'moving_average' end
      from public.v_stock_position sp
     where l.invoice_id = p_invoice_id
       and not v_imported
       and sp.grade_id  = l.grade_id
       and sp.size_id   = l.size_id;

    -- ── 6 · and the stock leaves again ─────────────────────────────────────
    -- SALE: an ordinary invoice in full (step 4 proved it fits); an imported one up to what each
    -- bucket holds, lines in order -- 0051's rule, on the selection. REJECTION: in full, a record.
    with wanted as (
        select l.line_id, l.grade_id, l.size_id, l.price_per_ct,
               coalesce(l.selection_ct, 0) as selection_ct,
               coalesce(l.rejection_ct, 0) as rejection_ct
          from public.sales_line l
         where l.invoice_id = p_invoice_id
    ),
    capped as (
        select w.*,
               case when not v_imported then w.selection_ct
                    else greatest(0, least(w.selection_ct,
                             greatest(coalesce(p.balance_ct, 0), 0)
                             - coalesce(sum(w.selection_ct) over (partition by w.grade_id, w.size_id
                                                                  order by w.line_id
                                                                  rows between unbounded preceding and 1 preceding), 0)))
               end as sale_out
          from wanted w
          left join public.v_stock_position p
                 on p.grade_id = w.grade_id and p.size_id = w.size_id
    )
    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct,
         price_per_ct, ref_type, ref_id, created_by, reason)
    select p_invoice_date, c.grade_id, c.size_id, 'SALE', c.sale_out,
           c.price_per_ct, 'sales_line', c.line_id, auth.uid(), v_note
      from capped c where c.sale_out > 0
    union all
    select p_invoice_date, c.grade_id, c.size_id, 'REJECTION', c.rejection_ct,
           c.price_per_ct, 'sales_line', c.line_id, auth.uid(), v_note
      from capped c where c.rejection_ct > 0;

    -- ── 7 · the header, keeping the number and the status ──────────────────
    update public.sales_invoice
       set invoice_date = p_invoice_date,
           buyer_id     = p_buyer_id,
           broker_id    = p_broker_id,
           broker_pct   = p_broker_pct,
           terms_days   = p_terms_days,
           doc_type     = p_doc_type,
           currency_id  = p_currency_id,
           updated_by   = auth.uid()
     where invoice_id = p_invoice_id;

    return jsonb_build_object('ok', true, 'invoice_no', v_no, 'reason', v_reason);
end;
$$;

comment on function public.edit_posted_invoice is
    '0055. Corrects a POSTED invoice in one transaction: deletes its SALE/REJECTION movements (and any 0042 import_edit adjustment), replaces its lines and writes them again. Only the SALE moves stock: an ordinary invoice is refused when a bucket cannot cover its selection; an imported one is capped on its selection (0051). REJECTION is written in full as a record. A 0055 rejection hold on the invoice is left alone. Supersedes 0054.';


-- ── 5 · the sales import ────────────────────────────────────────────────────
-- 0051's body. The cap, the shortfall and the carats reported are all on the SELECTION; the
-- rejection is written in full as a record. Holds are not 'sales_line' rows, so the delete of the
-- previous import's movements leaves them where they are.
create or replace function public.replace_imported_sales(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_old_ids     bigint[];
    v_deleted     integer := 0;
    v_invoices    integer := 0;
    v_lines       integer := 0;
    v_receipts    integer := 0;
    v_currency    bigint;
    v_stock_lines integer := 0;
    v_stock_ct    numeric := 0;
    v_short_ct    numeric := 0;
    v_short_bkts  integer := 0;
begin
    if p_payload is null or jsonb_typeof(p_payload->'invoices') <> 'array' then
        raise exception 'replace_imported_sales expects {"invoices": [...]}';
    end if;

    if jsonb_array_length(p_payload->'invoices') = 0 then
        raise exception 'replace_imported_sales was given no invoices';
    end if;

    v_currency := (p_payload->>'currency_id')::bigint;
    if v_currency is null then
        raise exception 'replace_imported_sales needs a currency_id';
    end if;

    select coalesce(array_agg(invoice_id), '{}')
      into v_old_ids
      from public.sales_invoice
     where invoice_no like 'MIG-%';

    if array_length(v_old_ids, 1) is not null then
        perform public.clear_import_edits(v_old_ids);

        delete from public.stock_movement
         where ref_type = 'sales_line'
           and ref_id in (select line_id from public.sales_line
                           where invoice_id = any(v_old_ids));

        delete from public.receipt     where invoice_id = any(v_old_ids);
        delete from public.sales_line  where invoice_id = any(v_old_ids);
        delete from public.sales_invoice where invoice_id = any(v_old_ids);
        get diagnostics v_deleted = row_count;
    end if;

    with incoming as (
        select inv from jsonb_array_elements(p_payload->'invoices') as inv
    ),
    written as (
        insert into public.sales_invoice
            (invoice_no, invoice_date, buyer_id, broker_id, broker_pct,
             terms_days, doc_type, currency_id, status,
             created_by, updated_by)
        select inv->>'invoice_no',
               (inv->>'invoice_date')::date,
               (inv->>'buyer_id')::bigint,
               nullif(inv->>'broker_id', '')::bigint,
               coalesce((inv->>'broker_pct')::numeric, 0),
               coalesce((inv->>'terms_days')::integer, 0),
               coalesce(inv->>'doc_type', 'BILL'),
               v_currency,
               'POSTED',
               auth.uid(),
               auth.uid()
          from incoming
        returning invoice_id, invoice_no
    )
    select count(*) into v_invoices from written;

    with incoming as (
        select inv->>'invoice_no' as no,
               jsonb_array_elements(coalesce(inv->'lines', '[]'::jsonb)) as ln
          from jsonb_array_elements(p_payload->'invoices') as inv
    )
    insert into public.sales_line
        (invoice_id, grade_id, size_id, gross_weight_ct, selection_ct,
         price_per_ct, ex_rate, less1_pct, less2_pct, remark)
    select i.invoice_id,
           (c.ln->>'grade_id')::bigint,
           (c.ln->>'size_id')::bigint,
           (c.ln->>'gross_weight_ct')::numeric,
           (c.ln->>'selection_ct')::numeric,
           (c.ln->>'price_per_ct')::numeric,
           coalesce((c.ln->>'ex_rate')::numeric, 1),
           coalesce((c.ln->>'less1_pct')::numeric, 0),
           coalesce((c.ln->>'less2_pct')::numeric, 0),
           nullif(c.ln->>'remark', '')
      from incoming c
      join public.sales_invoice i on i.invoice_no = c.no;

    get diagnostics v_lines = row_count;

    with incoming as (
        select inv->>'invoice_no' as no,
               (inv->>'received')::numeric as received,
               (inv->>'invoice_date')::date as on_date
          from jsonb_array_elements(p_payload->'invoices') as inv
    )
    insert into public.receipt (invoice_id, receipt_date, amount, method, created_by)
    select i.invoice_id, c.on_date, c.received, 'IMPORTED', auth.uid()
      from incoming c
      join public.sales_invoice i on i.invoice_no = c.no
     where c.received is not null and c.received > 0;

    get diagnostics v_receipts = row_count;

    -- 0055. The SELECTION is what leaves the bucket, so it is what is capped (0051's rule: oldest
    -- first, never below zero) and what is reported. The rejection is written in full as a record.
    with wanted as (
        select l.line_id, l.grade_id, l.size_id, l.price_per_ct,
               i.invoice_date,
               coalesce(l.selection_ct, 0) as selection_ct,
               coalesce(l.rejection_ct, 0) as rejection_ct
          from public.sales_line l
          join public.sales_invoice i on i.invoice_id = l.invoice_id
         where i.invoice_no like 'MIG-%'
    ),
    running as (
        select w.*,
               greatest(coalesce(p.balance_ct, 0), 0) as room,
               coalesce(sum(w.selection_ct) over (partition by w.grade_id, w.size_id
                                                  order by w.invoice_date, w.line_id
                                                  rows between unbounded preceding and 1 preceding), 0)
                   as taken_before
          from wanted w
          left join public.v_stock_position p
                 on p.grade_id = w.grade_id and p.size_id = w.size_id
    ),
    capped as (
        select r.*,
               greatest(0, least(r.selection_ct, r.room - r.taken_before)) as sale_out
          from running r
    ),
    wrote as (
        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
             price_per_ct, ref_type, ref_id, created_by)
        select c.invoice_date, c.grade_id, c.size_id, 'SALE', c.sale_out,
               c.price_per_ct, 'sales_line', c.line_id, auth.uid()
          from capped c
         where c.sale_out > 0
        union all
        select c.invoice_date, c.grade_id, c.size_id, 'REJECTION', c.rejection_ct,
               c.price_per_ct, 'sales_line', c.line_id, auth.uid()
          from capped c
         where c.rejection_ct > 0
        returning movement_type, weight_ct
    ),
    took as (
        -- What actually LEFT stock: the SALE rows only.
        select coalesce(sum(weight_ct) filter (where movement_type = 'SALE'), 0) as ct_out from wrote
    ),
    counted as (
        select count(*) filter (where c.sale_out > 0) as lines_out from capped c
    ),
    fell_short as (
        select coalesce(round(sum(c.selection_ct - c.sale_out), 4), 0) as short_ct,
               count(distinct (c.grade_id, c.size_id))                as short_buckets
          from capped c
         where c.selection_ct - c.sale_out > 0.00005
    )
    select counted.lines_out, round(took.ct_out, 4),
           fell_short.short_ct, fell_short.short_buckets
      into v_stock_lines, v_stock_ct, v_short_ct, v_short_bkts
      from took, counted, fell_short;

    return jsonb_build_object('ok', true, 'deleted', v_deleted,
                              'invoices', v_invoices, 'lines', v_lines,
                              'receipts', v_receipts,
                              'stock_lines', v_stock_lines,
                              'stock_ct', v_stock_ct,
                              'short_ct', v_short_ct,
                              'short_buckets', v_short_bkts);
end;
$$;

comment on function public.replace_imported_sales is
    '0055. Replaces the imported MIG- sales history in one transaction. Each line writes a SALE for its selection, capped oldest-first at what the bucket holds and never below zero (0051), and a REJECTION for its rejection as a record that moves no stock. stock_ct / short_ct / short_buckets report the SELECTION. Never deletes 0055 rejection holds, so a re-import cannot add history back. Supersedes 0051.';


-- ── 6 · cancelling: give back what was taken, and nothing that was not ───────
-- 0010's body. SALE only (a 0055 rejection never left), plus the invoice's own hold if it has one,
-- because that hold IS this invoice's old rejection deduction -- releasing it is what cancelling did
-- before 0055, when the whole gross came back.
create or replace function public.cancel_invoice(p_invoice_id bigint, p_reason text default null)
returns jsonb
language plpgsql
as $$
declare
    v_status text;
begin
    select status into v_status
      from public.sales_invoice where invoice_id = p_invoice_id;

    if not found then
        raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
    end if;

    if v_status = 'CANCELLED' then
        return jsonb_build_object('ok', true, 'already_cancelled', true);
    end if;

    if p_reason is null or btrim(p_reason) = '' then
        raise exception 'Cancelling an invoice requires a reason';
    end if;

    if v_status = 'POSTED' then
        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
             price_per_ct, ref_type, ref_id, created_by, reason)
        select current_date, m.grade_id, m.size_id, 'ADJUST', m.weight_ct,
               m.price_per_ct, 'cancel', p_invoice_id, auth.uid(),
               'Reversal of invoice ' || p_invoice_id || ': ' || p_reason
          from public.stock_movement m
          join public.sales_line l on l.line_id = m.ref_id
         where m.ref_type = 'sales_line'
           and l.invoice_id = p_invoice_id
           and m.movement_type = 'SALE'                       -- 0055: the rejection never left
        union all
        select current_date, h.grade_id, h.size_id, 'ADJUST', -h.weight_ct,
               null, 'cancel', p_invoice_id, auth.uid(),
               'Reversal of invoice ' || p_invoice_id || ' (its pre-0055 rejection hold): ' || p_reason
          from public.stock_movement h
         where h.ref_type = 'rejection_hold'
           and h.ref_id = p_invoice_id;
    end if;

    update public.sales_invoice
       set status = 'CANCELLED', updated_by = auth.uid()
     where invoice_id = p_invoice_id;

    return jsonb_build_object('ok', true, 'reason', p_reason);
end;
$$;


-- ── 7 · a rejection recorded by hand: a record, not a withdrawal ────────────
-- The live body with the stock check removed: a rejection no longer takes carats out, so there is
-- nothing for the bucket to cover. Movement and dispositions are written exactly as before.
create or replace function public.record_rejection(
    p_grade_id     bigint,
    p_size_id      bigint,
    p_weight_ct    numeric,
    p_price_per_ct numeric default null,
    p_date         date    default current_date,
    p_client_ref   uuid    default null,
    p_dispositions jsonb   default '[]'::jsonb
)
returns jsonb
language plpgsql
as $$
declare
    v_movement_id bigint;
    v_kept        integer := 0;
begin
    if p_weight_ct is null or p_weight_ct <= 0 then
        raise exception 'Rejection weight must be greater than zero';
    end if;

    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct,
         price_per_ct, ref_type, created_by, client_ref)
    values (p_date, p_grade_id, p_size_id, 'REJECTION', p_weight_ct,
            p_price_per_ct, 'manual', auth.uid(), p_client_ref)
    returning movement_id into v_movement_id;

    if jsonb_typeof(p_dispositions) = 'array' and jsonb_array_length(p_dispositions) > 0 then
        insert into public.rejection_disposition (movement_id, to_grade_id, weight_ct, note, created_by)
        select v_movement_id, nullif(d->>'to_grade_id', '')::bigint, (d->>'weight_ct')::numeric,
               nullif(d->>'note', ''), auth.uid()
          from jsonb_array_elements(p_dispositions) as d
         where (d->>'weight_ct')::numeric > 0;
        get diagnostics v_kept = row_count;
    end if;

    return jsonb_build_object('ok', true, 'warning', null, 'movement_id', v_movement_id,
                              'dispositions', v_kept);
end;
$$;


-- ── 8 · and prove the position did not move ─────────────────────────────────
do $$
declare
    v_bad integer;
    v_eg  text;
begin
    select count(*), min(format('grade %s x size %s: %s -> %s', b.grade_id, b.size_id, b.ledger_ct, a.ledger_ct))
      into v_bad, v_eg
      from m0055_before b
      join public.v_stock_position a on a.grade_id = b.grade_id and a.size_id = b.size_id
     where a.ledger_ct <> b.ledger_ct;

    if v_bad > 0 then
        raise exception '0055 would change % bucket(s), e.g. %. Nothing was applied.', v_bad, v_eg;
    end if;
end;
$$;

commit;


-- ---------------------------------------------------------------------------
-- Verification. Every row must read 'ok'.
-- ---------------------------------------------------------------------------
select 'a REJECTION no longer moves the balance' as check,
       case when pg_get_viewdef('public.v_stock_position'::regclass) ilike '%REJECTION%'
            then 'ok' else 'NOT APPLIED' end as status
union all
select 'every old rejection is held, carat for carat',
       case when (select coalesce(sum(weight_ct), 0) from public.stock_movement
                   where movement_type = 'REJECTION'
                     and created_at < (select min(created_at) from public.stock_movement
                                        where ref_type in ('rejection_hold', 'rej_hold_mvmt')))
               = -(select coalesce(sum(weight_ct), 0) from public.stock_movement
                    where ref_type in ('rejection_hold', 'rej_hold_mvmt'))
            then 'ok' else 'HOLDS DO NOT MATCH' end
union all
select 'posting needs the selection only',
       case when pg_get_functiondef('public.post_invoice'::regproc) like '%sum(selection_ct) as out_ct%'
            then 'ok' else 'NOT APPLIED' end
union all
select 'cancelling gives back SALE only, plus the invoice''s hold',
       case when pg_get_functiondef('public.cancel_invoice'::regproc) like '%rejection_hold%'
            then 'ok' else 'NOT APPLIED' end
union all
select 'a hand-recorded rejection no longer checks stock',
       case when pg_get_functiondef('public.record_rejection'::regproc) not like '%assert_stock%'
            then 'ok' else 'NOT APPLIED' end;


-- ###########################################################################
-- SECTION 3 of 10 : 0056_pair_1mb_with_minus2.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0056. 1MB is sold in sieve -2.
--
-- 0018 seeded grade_size as "every size except -2, which is NO 1 and NO 1 BB only", and 0029 gave
-- 1MB the same rule. The client's own sheets say otherwise: their printed stock sheet carries a
-- 1MB -2 row, their rate sheet prices it (stock_sheet_rates "1MB,-2,42000"), and their sales file
-- sells it (sale upload (2).xlsx row 52, MIG-16). The stock import let it in -- the pairing
-- trigger is on sales_line only -- so Priya holds 10.95 ct of 1MB x -2 that no sale could take,
-- and a sales file naming it was refused whole: "Grade 1MB does not use size -2".
--
-- Adds that one pairing, and any other bucket that ALREADY holds stock without one, since stock
-- that cannot be sold is the same fault wherever it sits. Adds rows only; changes no stock.
-- Safe to run repeatedly.
-- ---------------------------------------------------------------------------
begin;

insert into public.grade_size (grade_id, size_id)
select g.grade_id, s.size_id
  from public.grade g join public.size_bucket s on s.code = '-2'
 where g.code = '1MB'
on conflict do nothing;

insert into public.grade_size (grade_id, size_id)
select distinct m.grade_id, m.size_id
  from public.stock_movement m
on conflict do nothing;

commit;

-- Verification. Both rows must read 'ok'.
select '1MB can be sold in -2' as check,
       case when exists (select 1 from public.grade_size gs
                           join public.grade g on g.grade_id = gs.grade_id
                           join public.size_bucket s on s.size_id = gs.size_id
                          where g.code = '1MB' and s.code = '-2')
            then 'ok' else 'MISSING' end as status
union all
select 'no stock sits in a bucket that cannot be sold',
       case when not exists (select 1 from public.stock_movement m
                              where not exists (select 1 from public.grade_size gs
                                                 where gs.grade_id = m.grade_id and gs.size_id = m.size_id))
            then 'ok' else 'STILL UNPAIRED' end;


-- ###########################################################################
-- SECTION 4 of 10 : 0057_merge_fl_and_colour_into_ii.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0057. FL, NO II (#) and COL (color) become ONE grade, Roman II.
--
-- WHY. The office reads the three as one grade, "II". Until now they were shown together on the
-- Stock report and Stock page only (display grouping); every picker, filter, sale and stock check
-- still kept them apart. This makes it real.
--
-- HOW. NO II (the grade with the most history) is kept and every row that pointed at FL or COL is
-- moved onto it: ledger movements (both sides of a conversion), sales lines, intake parcels,
-- holds, rejection destinations and prices. Nothing is deleted except the two emptied catalogue
-- rows. Carats are not recomputed -- v_stock_position sums the moved movements, so II holds
-- exactly FL + # + color, bucket by bucket. The check at the end proves it and rolls back if not.
--
-- The old spellings become II's aliases, so a sheet or sales file that still prints "FL", "#" or
-- "color" imports into II rather than offering to create a grade.
--
-- KEPT AS IT WAS. Code stays 'NO II' (saved settings and the sheet rates refer to it); the app
-- prints it as "II". The FL and COL entries in app_config.stock_sheet_rates are left untouched
-- and simply no longer match a grade -- the app skips them. Audit history is kept; the moves
-- below add their own audit rows, which is the record that this was done.
--
-- One transaction. Refuses, changing nothing, if a grade is missing, or if a conversion ran
-- between two of the three (it would become a conversion from II into II).
-- ---------------------------------------------------------------------------
begin;

-- What was moved, so ROLLBACK_0057.sql can put every row back exactly. RLS on and no policy: the
-- API cannot read them, only the SQL editor.
create table if not exists public.merge_0057_grade      as select * from public.grade      with no data;
create table if not exists public.merge_0057_grade_size as select * from public.grade_size with no data;
create table if not exists public.merge_0057_moved
    (tbl text not null, row_id bigint not null, col text not null, old_grade_id bigint not null);
alter table public.merge_0057_grade      enable row level security;
alter table public.merge_0057_grade_size enable row level security;
alter table public.merge_0057_moved      enable row level security;

do $$
declare
    v_ii  bigint := (select grade_id from public.grade where code = 'NO II');
    v_fl  bigint := (select grade_id from public.grade where code = 'FL');
    v_col bigint := (select grade_id from public.grade where code = 'COL');
    v_old bigint[];
    v_before jsonb;
    v_after  jsonb;
begin
    if v_ii is null then raise exception '0057: grade NO II not found. Nothing was changed.'; end if;
    if v_fl is null and v_col is null then
        raise notice '0057: FL and COL are already gone. Nothing to do.';
        return;
    end if;
    v_old := array_remove(array[v_fl, v_col], null);

    if exists (select 1 from public.stock_movement
                where counterparty_grade_id is not null
                  and grade_id = any(v_old || v_ii) and counterparty_grade_id = any(v_old || v_ii)) then
        raise exception '0057: a conversion ran between FL, # and color. Nothing was changed.';
    end if;

    -- Carats per sieve across the three, before.
    select jsonb_object_agg(size_code, ct) into v_before from (
        select size_code, sum(ledger_ct) ct
          from public.v_stock_position where grade_code in ('NO II', 'FL', 'COL') group by size_code) t;

    insert into public.merge_0057_grade      select * from public.grade      where grade_id = any(v_old || v_ii);
    insert into public.merge_0057_grade_size select * from public.grade_size where grade_id = any(v_old || v_ii);
    insert into public.merge_0057_moved
    select 'stock_movement', movement_id, 'grade_id', grade_id from public.stock_movement where grade_id = any(v_old)
    union all select 'stock_movement', movement_id, 'counterparty_grade_id', counterparty_grade_id
                from public.stock_movement where counterparty_grade_id = any(v_old)
    union all select 'sales_line', line_id, 'grade_id', grade_id from public.sales_line where grade_id = any(v_old)
    union all select 'rough_intake', intake_id, 'grade_id', grade_id from public.rough_intake where grade_id = any(v_old)
    union all select 'stock_reservation', reservation_id, 'grade_id', grade_id
                from public.stock_reservation where grade_id = any(v_old)
    union all select 'rejection_disposition', disposition_id, 'to_grade_id', to_grade_id
                from public.rejection_disposition where to_grade_id = any(v_old)
    union all select 'price_list', price_id, 'grade_id', grade_id from public.price_list where grade_id = any(v_old);

    -- II is paired with every sieve any of the three was paired with (sales_line_grade_size_guard).
    insert into public.grade_size (grade_id, size_id)
    select distinct v_ii, size_id from public.grade_size where grade_id = any(v_old)
    on conflict do nothing;

    update public.stock_movement        set grade_id = v_ii              where grade_id = any(v_old);
    update public.stock_movement        set counterparty_grade_id = v_ii where counterparty_grade_id = any(v_old);
    update public.sales_line            set grade_id = v_ii              where grade_id = any(v_old);
    update public.rough_intake          set grade_id = v_ii              where grade_id = any(v_old);
    update public.stock_reservation     set grade_id = v_ii              where grade_id = any(v_old);
    update public.rejection_disposition set to_grade_id = v_ii           where to_grade_id = any(v_old);
    update public.price_list            set grade_id = v_ii              where grade_id = any(v_old);

    -- The old codes and their spellings resolve to II from now on. First in the sheet's order.
    update public.grade g
       set display_name = 'II',
           sort_order   = (select min(sort_order) from public.grade where grade_id = any(v_old || v_ii)),
           aliases      = (select string_agg(distinct a, ';')
                             from public.grade x,
                                  unnest(string_to_array(coalesce(x.aliases, ''), ';') || x.code) a
                            where x.grade_id = any(v_old || v_ii) and a <> '' and a <> 'NO II')
     where g.grade_id = v_ii;

    delete from public.grade where grade_id = any(v_old);      -- their grade_size rows cascade

    -- Carats per sieve, after: must equal before.
    select jsonb_object_agg(size_code, ct) into v_after from (
        select size_code, sum(ledger_ct) ct
          from public.v_stock_position where grade_code = 'NO II' group by size_code) t;

    if coalesce(v_before, '{}') <> coalesce(v_after, '{}') then
        raise exception '0057: carats changed (before %, after %). Nothing was changed.', v_before, v_after;
    end if;
end;
$$;

commit;

-- Verification: FL and COL gone, II holds what the three held.
select code, display_name, sort_order, aliases from public.grade where code in ('NO II', 'FL', 'COL');
select size_code, balance_ct, reserved_ct, ledger_ct from public.v_stock_position
 where grade_code = 'NO II' order by size_code;


-- ###########################################################################
-- SECTION 5 of 10 : 0058_invoice_cost_on_selection_and_cancel_at_cost.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0058. Two invoice calculations that 0055 left behind.
--
-- 1 · INVOICE COST IS CHARGED ON THE CARATS SOLD, NOT THE WHOLE PARCEL.
--     v_invoice.cost_total was cost_per_ct x gross_weight_ct (0019/0020): "the whole parcel left
--     stock". Since 0055 the rejected carats never leave -- they stay in stock and in its value --
--     so charging them to the sale counted them twice and turned a profitable invoice into a loss
--     (Priya INV-2026-00002: 189.70 ct charged, 78.24 ct sold, margin -37,03,183.69 instead of
--     +54,463.95). Now cost_per_ct x selection_ct, the same carats revenue is charged on.
--     Only the view changes; no row is touched. margin and margin_summary follow from it.
--
-- 2 · A CANCELLED INVOICE RETURNS ITS STONES AT WHAT THEY COST, NOT WHAT THEY SOLD FOR.
--     cancel_invoice put the sold carats back as a positive ADJUST priced at the SALE movement's
--     price -- the selling price, in the invoice's currency. Every positive ADJUST counts as a
--     purchase in avg_cost, so a cancellation bought the stones back at the selling price: a
--     rupee sale pushed the bucket's average cost up by the margin, a dollar sale ($285 x 95.66)
--     came back at Rs 285 a carat and collapsed it. Now each line comes back at the cost stamped
--     on it when it was posted (sales_line.cost_per_ct); a line with no stamp (imported sales)
--     comes back at the bucket's current average cost. The pre-0055 rejection-hold reversal had
--     the same flaw with no price at all (free stones, average pulled down) and now also comes
--     back at the bucket's average cost.
--     Existing cancellation rows are NOT rewritten.
--
-- Nothing else in either object changes. Columns of v_invoice are unchanged in name and order.
-- ---------------------------------------------------------------------------
begin;

create or replace view public.v_invoice as
 SELECT i.invoice_id,
    i.invoice_no,
    i.invoice_date,
    i.buyer_id,
    b.name AS buyer_name,
    b.credit_limit,
    i.broker_id,
    br.name AS broker_name,
    i.broker_pct,
    i.terms_days,
    i.doc_type,
    i.status,
    i.created_by,
    p.full_name AS salesperson,
    COALESCE(t.amount_total, (0)::numeric) AS amount_total,
    COALESCE(t.carats_sold, (0)::numeric) AS carats_sold,
    COALESCE(r.received, (0)::numeric) AS received,
        CASE
            WHEN ((i.status)::text = 'CANCELLED'::text) THEN (0)::numeric
            ELSE round((COALESCE(t.amount_total, (0)::numeric) - COALESCE(r.received, (0)::numeric)), 2)
        END AS outstanding,
        CASE
            WHEN (COALESCE(t.carats_sold, (0)::numeric) > (0)::numeric) THEN (COALESCE(t.amount_total, (0)::numeric) / t.carats_sold)
            ELSE (0)::numeric
        END AS blended_rate,
    round(((COALESCE(t.amount_pre_broker, (0)::numeric) * i.broker_pct) / (100)::numeric), 2) AS broker_payable,
    (i.invoice_date + i.terms_days) AS due_date,
    ((CURRENT_DATE > (i.invoice_date + i.terms_days)) AND ((COALESCE(t.amount_total, (0)::numeric) - COALESCE(r.received, (0)::numeric)) > 0.01) AND ((i.status)::text = 'POSTED'::text)) AS is_overdue,
    GREATEST(0, (CURRENT_DATE - (i.invoice_date + i.terms_days))) AS days_overdue,
    i.created_at,
    i.updated_at,
        CASE
            WHEN ((c.lines_total > 0) AND (c.lines_costed = c.lines_total)) THEN round(c.cost_total, 2)
            ELSE NULL::numeric
        END AS cost_total,
        CASE
            WHEN ((i.status)::text = 'CANCELLED'::text) THEN NULL::numeric
            WHEN ((c.lines_total > 0) AND (c.lines_costed = c.lines_total)) THEN round((COALESCE(t.amount_total, (0)::numeric) - c.cost_total), 2)
            ELSE NULL::numeric
        END AS margin,
        CASE
            WHEN (c.lines_total > 0) THEN round(((c.lines_costed)::numeric / (c.lines_total)::numeric), 4)
            ELSE (0)::numeric
        END AS cost_coverage,
    COALESCE(c.lines_total, (0)::bigint) AS line_count
   FROM ((((((sales_invoice i
     JOIN buyer b ON ((b.buyer_id = i.buyer_id)))
     LEFT JOIN broker br ON ((br.broker_id = i.broker_id)))
     LEFT JOIN profiles p ON ((p.id = i.created_by)))
     LEFT JOIN LATERAL ( SELECT sum(vl.amount) AS amount_total,
            sum(vl.amount_pre_broker) AS amount_pre_broker,
            sum(vl.selection_ct) AS carats_sold
           FROM v_sales_line vl
          WHERE (vl.invoice_id = i.invoice_id)) t ON (true))
     LEFT JOIN LATERAL ( SELECT sum(rc.amount) AS received
           FROM receipt rc
          WHERE (rc.invoice_id = i.invoice_id)) r ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS lines_total,
            count(sl.cost_per_ct) AS lines_costed,
            sum((sl.cost_per_ct * sl.selection_ct)) AS cost_total       -- 0058: was gross_weight_ct
           FROM sales_line sl
          WHERE (sl.invoice_id = i.invoice_id)) c ON (true));

create or replace function public.cancel_invoice(p_invoice_id bigint, p_reason text default null::text)
 returns jsonb
 language plpgsql
as $function$
declare
    v_status text;
begin
    select status into v_status
      from public.sales_invoice where invoice_id = p_invoice_id;

    if not found then
        raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found';
    end if;

    if v_status = 'CANCELLED' then
        return jsonb_build_object('ok', true, 'already_cancelled', true);
    end if;

    if p_reason is null or btrim(p_reason) = '' then
        raise exception 'Cancelling an invoice requires a reason';
    end if;

    if v_status = 'POSTED' then
        insert into public.stock_movement
            (movement_date, grade_id, size_id, movement_type, weight_ct,
             price_per_ct, ref_type, ref_id, created_by, reason)
        -- 0058: back at what the stones COST -- the stamp from posting, else the bucket's average.
        -- Never the selling price, which is a sale figure and may be in another currency.
        select current_date, m.grade_id, m.size_id, 'ADJUST', m.weight_ct,
               coalesce(l.cost_per_ct, nullif(sp.avg_cost, 0)), 'cancel', p_invoice_id, auth.uid(),
               'Reversal of invoice ' || p_invoice_id || ': ' || p_reason
          from public.stock_movement m
          join public.sales_line l on l.line_id = m.ref_id
          left join public.v_stock_position sp on sp.grade_id = m.grade_id and sp.size_id = m.size_id
         where m.ref_type = 'sales_line'
           and l.invoice_id = p_invoice_id
           and m.movement_type = 'SALE'                       -- 0055: the rejection never left
        union all
        select current_date, h.grade_id, h.size_id, 'ADJUST', -h.weight_ct,
               case when -h.weight_ct > 0 then nullif(sp.avg_cost, 0) end,   -- 0058: was null (free stones)
               'cancel', p_invoice_id, auth.uid(),
               'Reversal of invoice ' || p_invoice_id || ' (its pre-0055 rejection hold): ' || p_reason
          from public.stock_movement h
          left join public.v_stock_position sp on sp.grade_id = h.grade_id and sp.size_id = h.size_id
         where h.ref_type = 'rejection_hold'
           and h.ref_id = p_invoice_id;
    end if;

    update public.sales_invoice
       set status = 'CANCELLED', updated_by = auth.uid()
     where invoice_id = p_invoice_id;

    return jsonb_build_object('ok', true, 'reason', p_reason);
end;
$function$;

commit;


-- ###########################################################################
-- SECTION 6 of 10 : 0059_adjust_stock_refuses_free_increase.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0059. A stock increase always carries a cost.
--
-- adjust_stock takes no rate, and it accepted a positive weight: those carats entered the
-- average cost as free stones and dragged it down (Priya, 12 Oct: four "Repair Loss" rows of
-- +0.19 ct in all, no rate). adjust_stock_at_cost (0028) already refuses an increase without a
-- rate; the Intake page's Adjust box did not use it. The app now asks for a rate and sends
-- increases to adjust_stock_at_cost -- this closes the old door for every client, including an
-- older installed app.
--
-- Only the positive-weight case changes: it is refused with a sentence saying what to do.
-- Removals behave exactly as before. Existing rows are not touched.
-- ---------------------------------------------------------------------------
begin;

create or replace function public.adjust_stock(p_grade_id bigint, p_size_id bigint, p_weight_ct numeric,
                                               p_reason text, p_date date default current_date,
                                               p_client_ref uuid default null::uuid)
 returns jsonb
 language plpgsql
as $function$
declare
    v_warning text;
begin
    if p_weight_ct is null or p_weight_ct = 0 then
        raise exception 'An adjustment must move a non-zero weight';
    end if;
    if p_reason is null or btrim(p_reason) = '' then
        raise exception 'An adjustment reason is required';
    end if;
    -- 0059: an increase needs the rate those carats are worth -- adjust_stock_at_cost takes it.
    if p_weight_ct > 0 then
        raise exception 'Adding % ct needs the rate those carats are worth, or the average cost of this bucket is destroyed. Enter a rate per carat.', p_weight_ct;
    end if;
    v_warning := public.assert_stock(p_grade_id, p_size_id, -p_weight_ct);
    insert into public.stock_movement
        (movement_date, grade_id, size_id, movement_type, weight_ct, ref_type, reason, created_by, client_ref)
    values
        (p_date, p_grade_id, p_size_id, 'ADJUST', p_weight_ct, 'manual', btrim(p_reason), auth.uid(), p_client_ref);
    return jsonb_build_object('ok', true, 'warning', v_warning);
end;
$function$;

commit;


-- ###########################################################################
-- SECTION 7 of 10 : 0060_admin_end_sessions.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0060. Let the admin-users Edge Function end a user's sessions.
--
-- WHY. After a password reset or a deactivation, admin-users called
-- auth.admin.signOut(<user id>, 'global'). That supabase-js call takes the user's own JWT, not their
-- id (auth-js GoTrueAdminApi.signOut(jwt, scope): "jwt: A valid, logged-in JWT"), so the request
-- failed, the error was ignored, and the function itself never ended a session -- so a DEACTIVATED
-- user stayed signed in. GoTrue's admin API has no "sign out user by id", so this does it directly:
-- deleting a user's rows in auth.sessions ends them -- their refresh tokens go with them (FK cascade)
-- and their access tokens die at expiry, as with any sign-out.
--
-- WHO MAY CALL IT. Only service_role, i.e. only server code holding the service key (admin-users).
-- Revoked from public, anon and authenticated: no signed-in user can call it from the app.
--
-- Ending sessions matters for DEACTIVATION: tested on Demo (15 Oct 2026), a deactivated user's session
-- stayed alive. A password reset already ends every session in Supabase Auth itself; admin-users calls
-- this then too, as an explicit guarantee. p_keep_session (a session to spare) is optional and unused
-- by admin-users today -- Supabase ends the caller's own session on a password change regardless.
--
-- Returns how many sessions were ended. Touches nothing else.
-- ---------------------------------------------------------------------------
begin;

create or replace function public.admin_end_sessions(p_user uuid, p_keep_session uuid default null)
returns integer
language plpgsql
security definer
set search_path = auth, pg_temp
as $function$
declare
    v_ended integer;
begin
    if p_user is null then
        raise exception 'admin_end_sessions: no user given';
    end if;
    delete from auth.sessions
     where user_id = p_user
       and (p_keep_session is null or id <> p_keep_session);
    get diagnostics v_ended = row_count;
    return v_ended;
end;
$function$;

revoke all on function public.admin_end_sessions(uuid, uuid) from public, anon, authenticated;
grant execute on function public.admin_end_sessions(uuid, uuid) to service_role;

comment on function public.admin_end_sessions(uuid, uuid) is
    '0060. Ends a user''s sessions (all, or all but p_keep_session). service_role only: called by the admin-users Edge Function after a password reset or a deactivation.';

commit;

-- Check: only service_role (and the owner) may execute it.
select has_function_privilege('anon', 'public.admin_end_sessions(uuid, uuid)', 'execute')          as anon_can_call,
       has_function_privilege('authenticated', 'public.admin_end_sessions(uuid, uuid)', 'execute') as signed_in_can_call,
       has_function_privilege('service_role', 'public.admin_end_sessions(uuid, uuid)', 'execute')  as service_role_can_call;


-- ###########################################################################
-- SECTION 8 of 10 : 0061_authorise_definer_functions.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0061. Every SECURITY DEFINER function the app can call now checks WHO is calling.
--
-- WHY. Found 15 Oct 2026: these functions bypass row-level security (they run as their owner) and
-- were executable by any signed-in account with no role or active check -- so an INACTIVE account,
-- or a stranger who used the (then open) public sign-up, could e.g. call delete_imported_stock()
-- and wipe every imported holding, or replace the stock or the sales outright. The table policies
-- were right; these functions simply went around them.
--
-- HOW, without touching any function's logic:
--   * a function the app calls is renamed <name>__unchecked (and the app loses EXECUTE on it), and
--     a short function with the ORIGINAL name and the SAME arguments and defaults checks the caller,
--     then hands the call through unchanged. Allowed callers see exactly the behaviour they had.
--   * a function the app never calls loses EXECUTE for app users altogether. Other functions still
--     call it (they run as the owner), and the SQL editor still can.
-- Who may call what follows the table policies and the app: imports owner; grades/sizes manager or
-- owner; correcting a posted invoice manager/owner or the active user who created it; holds any
-- active staff; clearing a sign-in lockout only for your own address.
--
-- Also: a new profile starts INACTIVE (it was active by default -- a stranger signing up became an
-- active sales user). admin-users sets active explicitly when an owner creates a user.
--
-- Rollback: supabase/ROLLBACK_0061.sql. Safe to run twice: a function already wrapped is skipped.
-- ---------------------------------------------------------------------------
begin;

-- ── the check ────────────────────────────────────────────────────────────────
-- current_user_role() is null for an inactive profile or no profile, so both are refused.
create or replace function public.require_role(variadic p_roles text[])
returns void
language plpgsql
stable
set search_path = public, pg_temp
as $function$
begin
    if coalesce(public.current_user_role(), '') <> all (p_roles) then
        raise exception 'Not allowed: this needs an active % account.', array_to_string(p_roles, ' or ')
            using errcode = 'insufficient_privilege';
    end if;
end;
$function$;
revoke all on function public.require_role(text[]) from public, anon;
grant execute on function public.require_role(text[]) to authenticated, service_role;

-- ── rename the app-facing functions out of the way (skipped if already done) ─────────────────
do $$
declare
    f text;
begin
    foreach f in array array[
        'import_stock(date, jsonb, boolean, uuid, text)',
        'replace_imported_sales(jsonb)',
        'add_grade(text, text)',
        'add_size(text, text)',
        'edit_posted_invoice(bigint, date, bigint, bigint, numeric, integer, text, bigint, jsonb, text)',
        'reserve_line(uuid, text, bigint, bigint, numeric)',
        'release_line(uuid, text)',
        'release_entry(uuid)',
        'clear_login_failures(text)']
    loop
        if to_regprocedure('public.' || split_part(f, '(', 1) || '__unchecked(' || split_part(f, '(', 2)) is null then
            execute format('alter function public.%s rename to %I', f, split_part(f, '(', 1) || '__unchecked');
        end if;
        execute format('revoke all on function public.%s from public, anon, authenticated',
                       split_part(f, '(', 1) || '__unchecked(' || split_part(f, '(', 2));
    end loop;
end;
$$;

-- ── the guarded functions, original names and signatures ─────────────────────────────────────
create or replace function public.import_stock(p_as_at date, p_rows jsonb, p_replace boolean default true,
                                               p_batch uuid default null::uuid, p_source text default 'excel'::text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('owner');
    return public.import_stock__unchecked(p_as_at, p_rows, p_replace, p_batch, p_source);
end;
$function$;

create or replace function public.replace_imported_sales(p_payload jsonb)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('owner');
    return public.replace_imported_sales__unchecked(p_payload);
end;
$function$;

create or replace function public.add_grade(p_code text, p_display_name text default null::text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('manager', 'owner');
    return public.add_grade__unchecked(p_code, p_display_name);
end;
$function$;

create or replace function public.add_size(p_code text, p_display_name text default null::text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('manager', 'owner');
    return public.add_size__unchecked(p_code, p_display_name);
end;
$function$;

create or replace function public.edit_posted_invoice(p_invoice_id bigint, p_invoice_date date, p_buyer_id bigint,
                                                      p_broker_id bigint, p_broker_pct numeric, p_terms_days integer,
                                                      p_doc_type text, p_currency_id bigint, p_lines jsonb, p_reason text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
declare
    v_role text := public.current_user_role();   -- null: inactive, no profile, or logged out
begin
    -- A manager or owner may correct any invoice; an active sales user only one they created
    -- (invoice_update lets the creator write a POSTED row too). Unknown invoices fall through to
    -- the function's own "not found".
    --
    -- Written on the role itself, not as "not is_manager_or_owner() and not ...": for an inactive
    -- account those return NULL, NOT NULL is NULL, and an IF on NULL does not raise -- which let an
    -- inactive account through (caught on Demo, 15 Oct 2026).
    if v_role is null
       or v_role not in ('sales', 'manager', 'owner')
       or (v_role = 'sales'
           and not exists (select 1 from public.sales_invoice
                            where invoice_id = p_invoice_id and created_by = auth.uid())) then
        raise exception 'Not allowed: only a manager, an owner or the person who created this invoice may correct it.'
            using errcode = 'insufficient_privilege';
    end if;
    return public.edit_posted_invoice__unchecked(p_invoice_id, p_invoice_date, p_buyer_id, p_broker_id,
                                                 p_broker_pct, p_terms_days, p_doc_type, p_currency_id,
                                                 p_lines, p_reason);
end;
$function$;

create or replace function public.reserve_line(p_client_ref uuid, p_line_key text, p_grade_id bigint,
                                               p_size_id bigint, p_weight_ct numeric)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('sales', 'manager', 'owner');
    return public.reserve_line__unchecked(p_client_ref, p_line_key, p_grade_id, p_size_id, p_weight_ct);
end;
$function$;

create or replace function public.release_line(p_client_ref uuid, p_line_key text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('sales', 'manager', 'owner');
    return public.release_line__unchecked(p_client_ref, p_line_key);
end;
$function$;

create or replace function public.release_entry(p_client_ref uuid)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    perform public.require_role('sales', 'manager', 'owner');
    return public.release_entry__unchecked(p_client_ref);
end;
$function$;

-- Clearing a lockout: only your own, once signed in. Anyone could reset anyone's counter before,
-- which made the lockout pointless. The app calls it straight after a successful sign-in.
create or replace function public.clear_login_failures(p_email text)
returns void language plpgsql security definer set search_path = public, pg_temp as $function$
begin
    if auth.uid() is null or lower(coalesce(p_email, '')) <> lower(coalesce(auth.jwt() ->> 'email', '')) then
        raise exception 'Not allowed: a sign-in lockout can only be cleared by that account, once signed in.'
            using errcode = 'insufficient_privilege';
    end if;
    perform public.clear_login_failures__unchecked(p_email);
end;
$function$;

-- Who may call the guarded functions: signed-in users (the check above decides the rest).
revoke all on function public.import_stock(date, jsonb, boolean, uuid, text) from public, anon;
revoke all on function public.replace_imported_sales(jsonb) from public, anon;
revoke all on function public.add_grade(text, text) from public, anon;
revoke all on function public.add_size(text, text) from public, anon;
revoke all on function public.edit_posted_invoice(bigint, date, bigint, bigint, numeric, integer, text, bigint, jsonb, text) from public, anon;
revoke all on function public.reserve_line(uuid, text, bigint, bigint, numeric) from public, anon;
revoke all on function public.release_line(uuid, text) from public, anon;
revoke all on function public.release_entry(uuid) from public, anon;
revoke all on function public.clear_login_failures(text) from public, anon;
grant execute on function public.import_stock(date, jsonb, boolean, uuid, text) to authenticated, service_role;
grant execute on function public.replace_imported_sales(jsonb) to authenticated, service_role;
grant execute on function public.add_grade(text, text) to authenticated, service_role;
grant execute on function public.add_size(text, text) to authenticated, service_role;
grant execute on function public.edit_posted_invoice(bigint, date, bigint, bigint, numeric, integer, text, bigint, jsonb, text) to authenticated, service_role;
grant execute on function public.reserve_line(uuid, text, bigint, bigint, numeric) to authenticated, service_role;
grant execute on function public.release_line(uuid, text) to authenticated, service_role;
grant execute on function public.release_entry(uuid) to authenticated, service_role;
grant execute on function public.clear_login_failures(text) to authenticated, service_role;

-- ── functions the app never calls: app users lose EXECUTE ─────────────────────────────────────
-- delete_imported_stock wipes every imported holding; clear_import_edits is called only by
-- edit_posted_invoice and replace_imported_sales (as the owner, so unaffected); imported_edit_delta
-- is called by nothing. The SQL editor keeps them.
revoke all on function public.delete_imported_stock() from public, anon, authenticated;
revoke all on function public.clear_import_edits(bigint[]) from public, anon, authenticated;
revoke all on function public.imported_edit_delta(bigint, jsonb) from public, anon, authenticated;

-- ── a new profile starts inactive ─────────────────────────────────────────────────────────────
alter table public.profiles alter column active set default false;

commit;

-- PostgREST re-reads the functions now, not at its next restart.
notify pgrst, 'reload schema';

-- Check: what an app user can call now. Every row must read as expected.
select f as function,
       has_function_privilege('anon', ('public.' || f)::regprocedure, 'execute')          as anon,
       has_function_privilege('authenticated', ('public.' || f)::regprocedure, 'execute') as signed_in
  from unnest(array[
       -- guarded: anon false, signed_in true
       'import_stock(date,jsonb,boolean,uuid,text)', 'replace_imported_sales(jsonb)', 'add_grade(text,text)',
       'add_size(text,text)', 'edit_posted_invoice(bigint,date,bigint,bigint,numeric,integer,text,bigint,jsonb,text)',
       'reserve_line(uuid,text,bigint,bigint,numeric)', 'release_line(uuid,text)', 'release_entry(uuid)',
       'clear_login_failures(text)', 'require_role(text[])',
       -- originals and app-never-calls: anon false, signed_in false
       'import_stock__unchecked(date,jsonb,boolean,uuid,text)', 'replace_imported_sales__unchecked(jsonb)',
       'add_grade__unchecked(text,text)', 'add_size__unchecked(text,text)',
       'edit_posted_invoice__unchecked(bigint,date,bigint,bigint,numeric,integer,text,bigint,jsonb,text)',
       'reserve_line__unchecked(uuid,text,bigint,bigint,numeric)', 'release_line__unchecked(uuid,text)',
       'release_entry__unchecked(uuid)', 'clear_login_failures__unchecked(text)',
       'delete_imported_stock()', 'clear_import_edits(bigint[])', 'imported_edit_delta(bigint,jsonb)']) f;


-- ###########################################################################
-- SECTION 9 of 10 : 0063_color_is_its_own_grade.sql
-- ###########################################################################

-- ---------------------------------------------------------------------------
-- 0063. Color is its own grade again. "II Color" / "II Col" are II.
--
-- WHAT THE OFFICE ASKED FOR (20 Nov 2026)
--     II Color, II Col                    -> II   (grade NO II)
--     Color, COLOR, COLOUR, COL, C        -> Color (grade COL), never mixed with II
--
-- WHAT IT CHANGES -- the catalogue only:
--   1. Grade COL ("Color") comes back from 0057's own backup (merge_0057_grade), with its
--      original grade_id, sort order and sieve pairings, so anything that remembered id 14 still
--      means Color. If there is no backup, it is created fresh with II's sieves.
--   2. Its spellings (C, COL, color, COLOR, COLOUR) move from II's alias list back to COL.
--   3. II gains "II Color", "II Colour", "II Col" (and their spaceless forms).
--   4. Grade II COLOR, if migration 0062 was ever run, is removed -- but ONLY while nothing has
--      been recorded against it. If it holds data the migration refuses and changes nothing.
--
-- WHAT IT DOES NOT CHANGE
--   * No stock movement, sale, intake, price or receipt is moved or edited. Carats that 0057
--     moved into II stay in II -- after 13 Oct they cannot be told apart from II's own, and
--     moving a guess would change balances. On Priya the ledger is empty (reset 20 Nov), so
--     there is nothing to move. From now on a sheet or sale saying "Color" lands on Color.
--   * FL and # stay part of II, exactly as 0057 left them.
--
-- One transaction. Every check at the end must read 'ok'.
-- UNDO: ROLLBACK not needed for data (none moved); to merge again, re-run 0057.
-- ---------------------------------------------------------------------------
begin;

do $$
declare
    v_ii   bigint := (select grade_id from public.grade where code = 'NO II');
    v_iic  bigint := (select grade_id from public.grade where code = 'II COLOR');
    v_col  bigint := (select grade_id from public.grade where code = 'COL');
    v_used boolean;
    v_backup boolean := to_regclass('public.merge_0057_grade') is not null;
begin
    if v_ii is null then raise exception '0063: grade NO II not found. Nothing was changed.'; end if;

    -- 4. II COLOR (0062), only if it is empty.
    if v_iic is not null then
        select exists (select 1 from public.stock_movement where grade_id = v_iic or counterparty_grade_id = v_iic)
            or exists (select 1 from public.sales_line where grade_id = v_iic)
            or exists (select 1 from public.rough_intake where grade_id = v_iic)
            or exists (select 1 from public.stock_reservation where grade_id = v_iic)
            or exists (select 1 from public.rejection_disposition where to_grade_id = v_iic)
            or exists (select 1 from public.price_list where grade_id = v_iic)
          into v_used;
        if v_used then
            raise exception '0063: grade II COLOR already has stock, sales or prices recorded against it. Nothing was changed -- ask before moving them to II.';
        end if;
        delete from public.grade where grade_id = v_iic;          -- grade_size cascades
    end if;

    -- 2 (first half). Free the Color spellings from II, so no spelling ever names two grades.
    update public.grade
       set aliases = nullif(array_to_string(array(
               select a from unnest(string_to_array(coalesce(aliases, ''), ';')) a
                where a <> '' and coalesce(public.grade_key(a), '') not in ('C', 'COL', 'COLOR', 'COLOUR')), ';'), '')
     where grade_id = v_ii;

    -- 1. COL back.
    if v_col is null then
        if v_backup and exists (select 1 from public.merge_0057_grade where code = 'COL')
           and not exists (select 1 from public.grade g join public.merge_0057_grade b on b.grade_id = g.grade_id
                            where b.code = 'COL') then
            -- OVERRIDING SYSTEM VALUE: grade_id is an identity column (GENERATED ALWAYS), and this
            -- puts back the id Color had before 0057. The id sequence is already past it, so later
            -- grades are unaffected.
            insert into public.grade (grade_id, code, display_name, aliases, sort_order, active)
            overriding system value
            select grade_id, 'COL', 'Color', 'COLOUR;COLOR;C;color;Colour', sort_order, true
              from public.merge_0057_grade where code = 'COL';
        else
            insert into public.grade (code, display_name, aliases, sort_order, active)
            values ('COL', 'Color', 'COLOUR;COLOR;C;color;Colour',
                    (select coalesce(max(sort_order), 0) + 1 from public.grade), true);
        end if;
        v_col := (select grade_id from public.grade where code = 'COL');

        -- Its sieves: the ones it had before 0057, else the same as II's.
        if v_backup and exists (select 1 from public.merge_0057_grade_size s
                                  join public.merge_0057_grade b on b.grade_id = s.grade_id where b.code = 'COL') then
            insert into public.grade_size (grade_id, size_id)
            select v_col, s.size_id
              from public.merge_0057_grade_size s
              join public.merge_0057_grade b on b.grade_id = s.grade_id
              join public.size_bucket z on z.size_id = s.size_id
             where b.code = 'COL'
            on conflict do nothing;
        else
            insert into public.grade_size (grade_id, size_id)
            select v_col, size_id from public.grade_size where grade_id = v_ii
            on conflict do nothing;
        end if;
    else
        -- COL already there (0057 rolled back, say): just make sure it owns its spellings.
        update public.grade set aliases = 'COLOUR;COLOR;C;color;Colour', display_name = 'Color', active = true
         where grade_id = v_col;
    end if;

    -- 3. "II Color" / "II Col" are II.
    update public.grade
       set aliases = concat_ws(';', nullif(aliases, ''), 'II Color;II Colour;II Col;IICOLOR;IICOLOUR;IICOL')
     where grade_id = v_ii
       and not exists (select 1 from unnest(string_to_array(coalesce(aliases, ''), ';')) a
                        where public.grade_key(a) = 'IICOLOR');

    raise notice '0063: Color is grade % with % sieve(s); II aliases are now: %',
        v_col, (select count(*) from public.grade_size where grade_id = v_col),
        (select aliases from public.grade where grade_id = v_ii);
end $$;

commit;


-- ---------------------------------------------------------------------------
-- Verification (read-only). Every row must read 'ok'.
-- ---------------------------------------------------------------------------
with spelling(s, expect) as (values
        ('Color', 'COL'), ('COLOR', 'COL'), ('COLOUR', 'COL'), ('COL', 'COL'), ('C', 'COL'), ('color', 'COL'),
        ('II Color', 'NO II'), ('II Col', 'NO II'), ('II', 'NO II'), ('FL', 'NO II'), ('#', 'NO II')),
     owner as (
        select s.s, s.expect,
               (select string_agg(distinct g.code, ',')
                  from public.grade g
                 where g.code = s.s
                    or s.s = any(string_to_array(coalesce(g.aliases, ''), ';'))
                    or (public.grade_key(s.s) is not null
                        and (public.grade_key(g.code) = public.grade_key(s.s)
                             or exists (select 1 from unnest(string_to_array(coalesce(g.aliases, ''), ';')) a
                                         where public.grade_key(a) = public.grade_key(s.s))))) as got
          from spelling s)
select '"' || s || '" -> ' || expect as check, case when got = expect then 'ok' else 'GOT ' || coalesce(got, 'nothing') end as status
  from owner
union all
select 'Color has sieves', case when (select count(*) from public.grade_size gs join public.grade g using (grade_id) where g.code = 'COL') > 0 then 'ok' else 'NONE' end
union all
select 'no II COLOR grade left', case when not exists (select 1 from public.grade where code = 'II COLOR') then 'ok' else 'STILL THERE' end
union all
select 'no spelling belongs to two grades',
       case when not exists (
                select k from (
                    select public.grade_key(code) k, grade_id from public.grade
                    union
                    select public.grade_key(a), grade_id
                      from public.grade, unnest(string_to_array(coalesce(aliases, ''), ';')) a
                ) t where k is not null group by k having count(distinct grade_id) > 1)
            then 'ok' else 'CLASH' end;


-- ###########################################################################
-- SECTION 10 of 10 : the client's grade order (from supabase/set_grade_order.sql, company lock removed)
-- ###########################################################################

begin;

create temporary table wanted (code text primary key, ord integer) on commit drop;

insert into wanted (code, ord) values
    ('PREMIUM',  1),   -- PREMIUM
    ('1MB',      2),   -- 1 MB   (the screen shows a space; the code has none)
    ('NO 1 BB',  3),   -- 1 BB
    ('FL',       4),   -- FL
    ('NO II',    5),   -- #
    ('EX 1',     6),   -- Ex1
    ('NO 2',     7),   -- 2
    ('NO DX',    8),   -- DX1
    ('NO 3',     9),   -- 3
    ('NO 4',    10),   -- 4
    ('NO 5',    11),   -- 5
    ('NO 6',    12),   -- 6
    ('NO 7',    13),   -- 7
    ('TOP-COL', 14),   -- TOP co
    ('COL',     15),   -- color
    ('OW',      16),   -- OW
    ('LC 1',    17),   -- LC 1
    ('LC 2',    18),   -- LC 2
    ('GH',      19),   -- GH VS
    ('LB 1',    20),   -- LB 1
    ('LB 2',    21),   -- LB 2
    ('MIX',     22);   -- MIX


-- ── what this catalogue has, and what it does not ──────────────────────────
do $$
declare
    missing text;
    v_found integer;
begin
    select count(*) into v_found
      from wanted w
     where exists (select 1 from public.grade g where g.code = w.code);

    -- Not one of 22 matched. That is not a catalogue missing a grade, it is a
    -- list pointed at the wrong database -- or codes typed as marks, which is
    -- the mistake this list invites. Refuse before writing anything.
    if v_found = 0 then
        raise exception
            'None of the % listed codes is in this catalogue. Nothing changed -- this list is for a different database, or the codes have been written as marks ("#" for "NO II").',
            (select count(*) from wanted);
    end if;

    select string_agg(w.code, ', ' order by w.ord) into missing
      from wanted w
     where not exists (select 1 from public.grade g where g.code = w.code);

    if missing is not null then
        raise notice 'NOT IN THIS CATALOGUE, so skipped: %. The rest are ordered as listed.', missing;
    end if;

    raise notice '% of % listed grades found and placed.', v_found, (select count(*) from wanted);
end $$;


-- ── the listed grades take their places ────────────────────────────────────
update public.grade g
   set sort_order = w.ord
  from wanted w
 where g.code = w.code;

-- ── and everything else follows, keeping the order it already had ──────────
-- 100 upwards, so an unlisted grade can never collide with a listed one however
-- many are added to the list later.
with rest as (
    select g.grade_id,
           100 + row_number() over (order by g.sort_order, g.code) as ord
      from public.grade g
     where not exists (select 1 from wanted w where w.code = g.code)
)
update public.grade g
   set sort_order = r.ord
  from rest r
 where g.grade_id = r.grade_id;

commit;


-- ###########################################################################
-- FINAL CHECK. Every row must read 'ok'.
-- ###########################################################################
select item, status from (values
  (1,  '0054/0055 post_invoice takes only the selection',
       case when pg_get_functiondef('public.post_invoice(bigint, boolean)'::regprocedure) ilike '%selection%' then 'ok' else 'MISSING' end),
  (2,  '0055 cancel_invoice knows rejection holds',
       case when pg_get_functiondef('public.cancel_invoice'::regproc) ilike '%rejection_hold%' then 'ok' else 'MISSING' end),
  (3,  '0056 1MB can be sold in -2',
       case when exists (select 1 from public.grade_size gs join public.grade g using (grade_id)
                          join public.size_bucket s using (size_id) where g.code = '1MB' and s.code = '-2')
                 or not exists (select 1 from public.size_bucket where code = '-2')
                 or not exists (select 1 from public.grade where code = '1MB') then 'ok' else 'MISSING' end),
  (4,  '0057 FL is part of II',
       case when not exists (select 1 from public.grade where code = 'FL')
                 and to_regclass('public.merge_0057_moved') is not null then 'ok' else 'MISSING' end),
  (5,  '0058 cancel at cost',
       case when pg_get_functiondef('public.cancel_invoice'::regproc) ilike '%0058%' then 'ok' else 'MISSING' end),
  (6,  '0059 adjust_stock present',
       case when to_regproc('public.adjust_stock') is not null then 'ok' else 'MISSING' end),
  (7,  '0060 admin_end_sessions',
       case when to_regproc('public.admin_end_sessions') is not null then 'ok' else 'MISSING' end),
  (8,  '0061 require_role (security)',
       case when to_regproc('public.require_role') is not null then 'ok' else 'MISSING' end),
  (9,  '0063 Color is its own grade',
       case when exists (select 1 from public.grade where code = 'COL'
                          and 'color' = any(string_to_array(aliases, ';'))) then 'ok' else 'MISSING' end),
  (10, '0063 "II Color" is II',
       case when exists (select 1 from public.grade where code = 'NO II'
                          and 'II Color' = any(string_to_array(aliases, ';'))) then 'ok' else 'MISSING' end),
  (11, 'ORDER: MIX is 22, the paper ends there',
       case when (select sort_order from public.grade where code = 'MIX') = 22 then 'ok' else 'WRONG' end),
  (12, 'ORDER: no two grades share a place',
       case when not exists (select 1 from public.grade group by sort_order having count(*) > 1) then 'ok' else 'CLASH' end),
  (13, 'no spelling belongs to two grades',
       case when not exists (
                select k from (
                    select public.grade_key(code) k, grade_id from public.grade
                    union
                    select public.grade_key(a), grade_id
                      from public.grade, unnest(string_to_array(coalesce(aliases, ''), ';')) a) t
                 where k is not null group by k having count(distinct grade_id) > 1) then 'ok' else 'CLASH' end),
  (14, 'every active grade can be sold in some sieve',
       case when not exists (select 1 from public.grade g where g.active
                               and not exists (select 1 from public.grade_size s where s.grade_id = g.grade_id))
            then 'ok' else 'GRADE WITH NO SIEVE' end),
  (15, 'still empty: no invoices, no stock',
       case when not exists (select 1 from public.sales_invoice)
                 and not exists (select 1 from public.stock_movement) then 'ok' else 'HAS DATA' end)
) as t(ord, item, status)
order by ord;
